     * Коллбэк вызывается только для полных совпадений; лишние аргументы-компоненты
     * резолвятся через getComponent — семантика идентична Fleks iterate().
     */
    inline fun iterate(
        vararg classes: kotlin.reflect.KClass<*>,
        action: (Entity) -> Unit,
    ) {
        if (classes.isEmpty()) return
        val sa = stores[classes[0]] ?: return
        outer@ for (id in sa.items.indices) {
            if (aliveFlags.getOrNull(id) != true) continue
            for (c in classes) if (stores[c]?.get(id) == null) continue@outer
            action(entity(id))
        }
    }

